using ModelContextProtocol.Server;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer(options =>
{
    options.ServerInfo = new() { Name = "McpHttpServer", Version = "1.0.0" };
})
.WithHttpTransport()
.WithTools<WeatherTools>()
.WithResources<ConfigResources>();

var app = builder.Build();

app.MapMcp();

app.Run();

[McpServerToolType]
public sealed class WeatherTools
{
    [McpServerTool(Name = "get_weather", Title = "Get Weather"),
     System.ComponentModel.Description("Gets the current weather for a given city.")]
    public static string GetWeather(string city)
    {
        // Stub implementation — replace with a real API call.
        return $"{{\"city\":\"{city}\",\"temp_f\":72,\"condition\":\"Sunny\"}}";
    }
}

[McpServerResourceType]
public sealed class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "app_settings",
        Title = "Application Settings", MimeType = "application/json"),
     System.ComponentModel.Description("Returns the current application configuration.")]
    public static string GetAppSettings()
    {
        var settings = new
        {
            environment = "production",
            featureFlags = new { darkMode = true, betaAccess = false },
            maxConnections = 100,
            version = "1.0.0"
        };
        return System.Text.Json.JsonSerializer.Serialize(settings);
    }
}

